DROP TABLE IF EXISTS `adena_transactions`;
CREATE TABLE `adena_transactions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `character_name` varchar(100) DEFAULT NULL,
  `account_name` varchar(100) DEFAULT NULL,
  `ip_address` varchar(45) DEFAULT NULL,
  `hwid` varchar(255) DEFAULT NULL,
  `transaction_type` varchar(50) NOT NULL,
  `amount` bigint(20) NOT NULL DEFAULT 0,
  `balance_before` bigint(20) NOT NULL DEFAULT 0,
  `balance_after` bigint(20) NOT NULL DEFAULT 0,
  `severity` enum('LOW','MEDIUM','HIGH','CRITICAL') NOT NULL DEFAULT 'LOW',
  `details` text DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_adena_character` (`character_name`),
  KEY `idx_adena_account` (`account_name`),
  KEY `idx_adena_created` (`created_at`),
  KEY `idx_adena_amount` (`amount`),
  KEY `idx_adena_severity` (`severity`)
) ENGINE=InnoDB AUTO_INCREMENT=89 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

