  `strife_owner` int(11) NOT NULL DEFAULT 0,
  `avarice_dawn_score` int(11) NOT NULL DEFAULT 0,
  `gnosis_dawn_score` int(11) NOT NULL DEFAULT 0,
  `strife_dawn_score` int(11) NOT NULL DEFAULT 0,
  `avarice_dusk_score` int(11) NOT NULL DEFAULT 0,
  `gnosis_dusk_score` int(11) NOT NULL DEFAULT 0,
  `strife_dusk_score` int(11) NOT NULL DEFAULT 0,
  `accumulated_bonus0` bigint(20) NOT NULL DEFAULT 0,
  `accumulated_bonus1` bigint(20) NOT NULL DEFAULT 0,
  `accumulated_bonus2` bigint(20) NOT NULL DEFAULT 0,
  `accumulated_bonus3` bigint(20) NOT NULL DEFAULT 0,
  `accumulated_bonus4` bigint(20) NOT NULL DEFAULT 0
) ENGINE=MyISAM DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci ROW_FORMAT=FIXED;

