-- ----------------------------
-- Table structure for `siege_clans`
-- ----------------------------
DROP TABLE IF EXISTS `siege_clans`;
CREATE TABLE `siege_clans` (
  `residence_id` int(11) NOT NULL DEFAULT 0,
  `clan_id` int(11) NOT NULL DEFAULT 0,
  `type` varchar(255) NOT NULL,
  `param` bigint(20) NOT NULL,
  `date` bigint(20) NOT NULL,
  PRIMARY KEY (`residence_id`,`clan_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci ROW_FORMAT=DYNAMIC;

-- ----------------------------
-- Records of siege_clans
-- ----------------------------

-- ----------------------------
-- Table structure for `siege_guards`
-- ----------------------------
DROP TABLE IF EXISTS `siege_guards`;
CREATE TABLE `siege_guards` (
  `unitId` int(11) NOT NULL DEFAULT 0,
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `npcId` int(11) NOT NULL DEFAULT 0,
  `x` int(11) NOT NULL DEFAULT 0,
  `y` int(11) NOT NULL DEFAULT 0,
  `z` int(11) NOT NULL DEFAULT 0,
  `heading` int(11) NOT NULL DEFAULT 0,
  `respawnDelay` int(11) NOT NULL DEFAULT 0,
  `isHired` int(11) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`) USING BTREE,
  KEY `id` (`unitId`) USING BTREE
) ENGINE=MyISAM AUTO_INCREMENT=7516 DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci ROW_FORMAT=FIXED;

-- ----------------------------
-- Records of siege_guards
-- ----------------------------

-- ----------------------------
-- Table structure for `siege_players`
-- ----------------------------
DROP TABLE IF EXISTS `siege_players`;
CREATE TABLE `siege_players` (
  `residence_id` int(11) NOT NULL,
  `object_id` int(11) NOT NULL,
  `clan_id` int(11) NOT NULL,
  PRIMARY KEY (`residence_id`,`object_id`,`clan_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci ROW_FORMAT=DYNAMIC;

-- ----------------------------
-- Records of siege_players
-- ----------------------------

-- ----------------------------
-- Table structure for `stress_auto_rb`
-- ----------------------------
DROP TABLE IF EXISTS `stress_auto_rb`;
CREATE TABLE `stress_auto_rb` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `InvId` varchar(8) NOT NULL,
  `charId` int(11) NOT NULL DEFAULT 0,
  `OutSum` double(10,2) NOT NULL DEFAULT 0.00,
  `OutCount` int(11) NOT NULL DEFAULT 0,
  `trans_date` int(11) NOT NULL DEFAULT 0,
  `user_ip` varchar(30) NOT NULL DEFAULT '',
  `stage` enum('0','S','E','P','F') NOT NULL DEFAULT '0',
  `success` enum('0','1') NOT NULL DEFAULT '0',
  `comment` text NOT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  KEY `InvId` (`InvId`) USING BTREE
) ENGINE=MyISAM DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci ROW_FORMAT=DYNAMIC;

-- ----------------------------
-- Records of stress_auto_rb
-- ----------------------------

-- ----------------------------
-- Table structure for `stress_referal`
-- ----------------------------
DROP TABLE IF EXISTS `stress_referal`;
CREATE TABLE `stress_referal` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `account_referer` varchar(100) NOT NULL,
  `account_name` varchar(100) NOT NULL,
  `charId` int(11) NOT NULL DEFAULT 0,
  `char_name` varchar(30) NOT NULL,
  `success` enum('0','1') NOT NULL DEFAULT '0',
  `date` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `account_referer` (`account_referer`) USING BTREE
) ENGINE=MyISAM DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci ROW_FORMAT=DYNAMIC;

-- ----------------------------
-- Records of stress_referal
-- ----------------------------

-- ----------------------------
-- Table structure for `vote`
-- ----------------------------
DROP TABLE IF EXISTS `vote`;
CREATE TABLE `vote` (
  `id` int(11) NOT NULL DEFAULT 0,
  `HWID` varchar(32) NOT NULL DEFAULT '',
  `vote` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`,`HWID`,`vote`) USING BTREE,
  KEY `Index 2` (`id`,`vote`) USING BTREE,
  KEY `Index 3` (`id`) USING BTREE,
  KEY `Index 4` (`HWID`) USING BTREE
) ENGINE=MyISAM DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci ROW_FORMAT=DYNAMIC;

-- ----------------------------
-- Records of vote
-- ----------------------------

-- ----------------------------
-- Table structure for `vote_system`
-- ----------------------------
DROP TABLE IF EXISTS `vote_system`;
CREATE TABLE `vote_system` (
  `value_type` tinyint(4) NOT NULL DEFAULT 1,
  `value` char(100) NOT NULL DEFAULT '0',
  `penalty_time` decimal(20,0) DEFAULT 0
) ENGINE=MyISAM DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci ROW_FORMAT=FIXED;

-- ----------------------------
-- Records of vote_system
-- ----------------------------

-- ----------------------------
-- Table structure for `weapon`
-- ----------------------------
DROP TABLE IF EXISTS `weapon`;
CREATE TABLE `weapon` (
  `item_id` decimal(11,0) NOT NULL DEFAULT 0,
  `name` varchar(120) NOT NULL DEFAULT '0',
  `additionalname` varchar(120) NOT NULL DEFAULT '',
  `bodypart` varchar(15) NOT NULL DEFAULT 'none',
  `crystallizable` varchar(5) NOT NULL DEFAULT 'false',
  `weight` decimal(4,0) NOT NULL DEFAULT 0,
  `soulshots` decimal(2,0) NOT NULL DEFAULT 0,
  `spiritshots` decimal(1,0) NOT NULL DEFAULT 0,
  `material` varchar(11) NOT NULL DEFAULT 'wood',
  `crystal_type` varchar(4) NOT NULL DEFAULT 'none',
  `p_dam` decimal(5,0) NOT NULL DEFAULT 0,
  `rnd_dam` decimal(2,0) NOT NULL DEFAULT 0,
  `weaponType` varchar(10) NOT NULL DEFAULT 'none',
  `critical` decimal(2,0) NOT NULL DEFAULT 0,
  `hit_modify` decimal(6,5) NOT NULL DEFAULT 0.00000,
  `avoid_modify` decimal(2,0) NOT NULL DEFAULT 0,
  `shield_def` decimal(3,0) NOT NULL DEFAULT 0,
  `shield_def_rate` decimal(2,0) NOT NULL DEFAULT 0,
  `atk_speed` decimal(3,0) NOT NULL DEFAULT 0,
  `mp_consume` decimal(2,0) NOT NULL DEFAULT 0,
  `m_dam` decimal(3,0) NOT NULL DEFAULT 0,
  `duration` int(11) NOT NULL DEFAULT -1,
  `time` int(11) NOT NULL DEFAULT -1,
  `price` decimal(11,0) NOT NULL DEFAULT 0,
  `crystal_count` int(11) NOT NULL DEFAULT 0,
  `sellable` varchar(5) NOT NULL DEFAULT 'false',
  `dropable` varchar(5) NOT NULL DEFAULT 'false',
  `destroyable` varchar(5) NOT NULL DEFAULT 'false',
  `tradeable` varchar(5) NOT NULL DEFAULT 'false',
  `depositable` varchar(5) NOT NULL DEFAULT 'false',
  `enchant4_skill_id` decimal(11,0) NOT NULL DEFAULT 0,
  `enchant4_skill_lvl` decimal(11,0) NOT NULL DEFAULT 0,
  `onCast_skill_id` decimal(11,0) NOT NULL DEFAULT 0,
  `onCast_skill_lvl` decimal(11,0) NOT NULL DEFAULT 0,
  `onCast_skill_chance` decimal(11,0) NOT NULL DEFAULT 0,
  `onCrit_skill_id` decimal(11,0) NOT NULL DEFAULT 0,
  `onCrit_skill_lvl` decimal(11,0) NOT NULL DEFAULT 0,
  `onCrit_skill_chance` decimal(11,0) NOT NULL DEFAULT 0,
  `change_weaponId` decimal(11,0) NOT NULL DEFAULT 0,
  `skill` varchar(70) NOT NULL DEFAULT '0-0;',
  PRIMARY KEY (`item_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci ROW_FORMAT=DYNAMIC;

